-- SQL CORRIGE A PARTIR DES PDF + EXCEL
-- Type filaire verifie depuis les PDF : LICENCE / MASTER_PRO / MASTER_RECHERCHE / INGENIEUR / PREPA
-- Semestre : 2024 => SEMESTER1, 2025 => SEMESTER2

DROP DATABASE IF EXISTS gestion_examens;
CREATE DATABASE gestion_examens CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE gestion_examens;

CREATE TABLE filaire (
    id_filaire INT PRIMARY KEY,
    abreviation_filaire VARCHAR(50) NOT NULL,
    code_filaire VARCHAR(20) NULL,
    nom_filaire VARCHAR(150) NOT NULL,
    type_filaire ENUM('LICENCE','MASTER_PRO','MASTER_RECHERCHE','INGENIEUR','PREPA') NOT NULL,
    annee ENUM('1ERE','2EME','3EME') NOT NULL
);

CREATE TABLE proffer (
    id_proffer INT PRIMARY KEY,
    nom_professeur VARCHAR(150) NOT NULL
);

CREATE TABLE mataire (
    id_mataire INT PRIMARY KEY,
    code_matiere VARCHAR(20) NULL,
    nom_mataire VARCHAR(200) NOT NULL,
    id_proffe INT NULL,
    filaire_id INT NOT NULL,
    jour TINYINT NULL,
    type ENUM('DS','EXAMEN') NOT NULL,
    semestre ENUM('SEMESTER1','SEMESTER2') NOT NULL,
    FOREIGN KEY (id_proffe) REFERENCES proffer(id_proffer),
    FOREIGN KEY (filaire_id) REFERENCES filaire(id_filaire)
);

