-- =========================================================
-- PATCH corriger_2
-- Cette partie remplace la table mataire d'origine
-- par la version normalisee avec les colonnes:
--   ds TINYINT(1)
--   examen TINYINT(1)
-- et recharge les donnees INGENIEUR / PREPA
-- a partir du fichier migration_mataire_ing_prepa.sql
-- =========================================================

-- Migration de normalisation pour la table mataire
-- Source: schema_examens_corrige.sql + plans d'etudes INGENIEUR/PREPA (PDF).
USE gestion_examens;

DROP TABLE IF EXISTS mataire;
CREATE TABLE mataire (
    id_mataire INT PRIMARY KEY,
    nom_mataire VARCHAR(200) NOT NULL,
    id_proffe INT NULL,
    filaire_id INT NOT NULL,
    jour TINYINT NULL,
    semestre ENUM('SEMESTER1','SEMESTER2') NOT NULL,
    ds TINYINT(1) NOT NULL DEFAULT 0,
    examen TINYINT(1) NOT NULL DEFAULT 0,
    FOREIGN KEY (id_proffe) REFERENCES proffer(id_proffer),
    FOREIGN KEY (filaire_id) REFERENCES filaire(id_filaire),
    UNIQUE KEY uq_matiere_filaire_semestre (nom_mataire, filaire_id, semestre)
);

